// Coordinates and probability arrays are ordered [success, fallback, error].
// The trajectories are generated by the paper's sampled optimizer.
import { simplexData } from "./simplex-data.js";

const { configuration, trajectories } = simplexData;

const root = document.getElementById("simplex-demo");
const namespace = "http://www.w3.org/2000/svg";
const colors = { reinforce: "#4c78a8", graceful: "#e0822c" };
const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
const play = document.getElementById("simplex-play");
const replay = document.getElementById("simplex-restart");
const slider = document.getElementById("simplex-step");
const stepValue = document.getElementById("simplex-step-value");

function svgElement(name, attributes, text) {
  const element = document.createElementNS(namespace, name);
  for (const [key, value] of Object.entries(attributes)) element.setAttribute(key, value);
  if (text !== undefined) element.textContent = text;
  return element;
}

function position([success, fallback, error]) {
  return [180 * success + 42 * fallback + 318 * error, 62 * success + 274 * (fallback + error)];
}

function drawSimplex(svg) {
  svg.append(svgElement("path", { d: "M180 62 L42 274 L318 274 Z", class: "simplex-boundary" }));
  for (const fraction of [0.25, 0.5, 0.75]) {
    for (const pair of [
      [[fraction, 1 - fraction, 0], [fraction, 0, 1 - fraction]],
      [[1 - fraction, fraction, 0], [0, fraction, 1 - fraction]],
      [[1 - fraction, 0, fraction], [0, 1 - fraction, fraction]],
    ]) {
      const [start, end] = pair.map(position);
      svg.append(svgElement("line", { x1: start[0], y1: start[1], x2: end[0], y2: end[1], class: "simplex-gridline" }));
    }
  }
  for (const [name, outcome, x, y] of [
    ["Success", "S", 180, 26],
    ["Fallback", "F", 42, 299],
    ["Error", "E", 318, 299],
  ]) {
    svg.append(svgElement("text", { x, y, "text-anchor": "middle", class: "vertex-label" }, name));
    const probability = svgElement("text", { x, y: y + 17, "text-anchor": "middle", class: "vertex-probability" });
    probability.append(
      svgElement("tspan", { "font-style": "italic" }, "p"),
      svgElement("tspan", { "baseline-shift": "sub", "font-size": "9" }, outcome),
      document.createTextNode(" = 1"),
    );
    svg.append(probability);
  }
}

const panels = [...root.querySelectorAll(".simplex-method")].map((panel) => {
  const method = panel.dataset.method;
  const svg = panel.querySelector("svg");
  drawSimplex(svg);
  const histories = trajectories[method];
  const trails = histories.map((history, index) => {
    const coordinates = history.map((probabilities) => position(probabilities));
    const points = coordinates.map((point) => point.map((value) => value.toFixed(2)).join(","));
    const line = svgElement("polyline", { fill: "none", stroke: colors[method], "stroke-width": 2, "stroke-opacity": 0.8 });
    const [x, y] = coordinates[0];
    const initial = svgElement("circle", { cx: x, cy: y, r: 4, class: "initial-policy" });
    const current = svgElement("circle", { cx: x, cy: y, r: 4.5, fill: colors[method], stroke: "#fff", "stroke-width": 1.4, class: "current-policy" });
    initial.append(svgElement("title", {}, "Initial policy " + (index + 1) + ": " + configuration.initialPolicies[index].join(", ")));
    current.append(svgElement("title", {}, "Current policy " + (index + 1)));
    svg.append(line, initial, current);
    return { coordinates, points, line, current };
  });
  return { svg, histories, trails, metrics: panel.querySelector(".simplex-metrics") };
});

let step = reducedMotion.matches ? configuration.steps : 0;
let running = false;
let frame = null;
let previousTime = null;
let continuousStep = step;
let autoStarted = reducedMotion.matches;
let manuallyControlled = false;

function render(value) {
  step = Math.max(0, Math.min(configuration.steps, Math.round(value)));
  slider.value = String(step);
  slider.setAttribute("aria-valuetext", "Step " + step + " of " + configuration.steps);
  stepValue.value = step + " / " + configuration.steps;
  root.dataset.step = String(step);
  for (const panel of panels) {
    for (const trail of panel.trails) {
      trail.line.setAttribute("points", trail.points.slice(0, step + 1).join(" "));
      trail.current.setAttribute("cx", trail.coordinates[step][0]);
      trail.current.setAttribute("cy", trail.coordinates[step][1]);
    }
    const average = [0, 1, 2].map((index) =>
      panel.histories.reduce((sum, history) => sum + history[step][index], 0) / panel.histories.length);
    const reward = average[0] + configuration.caution * average[1];
    const successValue = document.createElement("strong");
    successValue.textContent = (100 * average[0]).toFixed(1) + "%";
    const rewardValue = document.createElement("strong");
    rewardValue.textContent = reward.toFixed(2);
    panel.metrics.replaceChildren("Mean success ", successValue, " · Mean reward ", rewardValue);
    panel.svg.setAttribute("aria-description", "Optimization step " + step + ". " + panel.metrics.textContent);
  }
}

function pause() {
  running = false;
  if (frame !== null) cancelAnimationFrame(frame);
  frame = null;
  previousTime = null;
  play.textContent = "Play";
  play.setAttribute("aria-label", step === configuration.steps ? "Play simplex animation from the beginning" : "Play simplex animation");
}

function tick(time) {
  if (!running) return;
  if (previousTime !== null) continuousStep += Math.min(time - previousTime, 100) * 0.02;
  previousTime = time;
  if (Math.round(continuousStep) !== step) render(continuousStep);
  if (continuousStep >= configuration.steps) {
    render(configuration.steps);
    pause();
    return;
  }
  frame = requestAnimationFrame(tick);
}

function start() {
  if (running) return;
  if (step === configuration.steps) render(0);
  continuousStep = step;
  previousTime = null;
  running = true;
  play.textContent = "Pause";
  play.setAttribute("aria-label", "Pause simplex animation");
  frame = requestAnimationFrame(tick);
}

play.addEventListener("click", () => {
  manuallyControlled = true;
  if (running) pause();
  else start();
});
replay.addEventListener("click", () => {
  manuallyControlled = true;
  pause();
  render(0);
  start();
});
slider.addEventListener("input", () => {
  manuallyControlled = true;
  pause();
  render(Number(slider.value));
  pause();
});

new IntersectionObserver((entries) => {
  const visible = entries[0].isIntersecting;
  if (!visible) pause();
  else if (!autoStarted && !manuallyControlled && !reducedMotion.matches) {
    autoStarted = true;
    start();
  }
}, { threshold: 0.3 }).observe(root);

document.addEventListener("visibilitychange", () => {
  if (document.hidden) pause();
});
reducedMotion.addEventListener("change", () => {
  if (reducedMotion.matches) {
    autoStarted = true;
    pause();
    render(configuration.steps);
    pause();
  }
});

root.querySelector(".simplex-fallback").hidden = true;
root.querySelector(".simplex-interactive").hidden = false;
render(step);
pause();
